        if 3 * k <= n:
            picked, out = set(), []
            if n:
                limit = _SPAN - _SPAN % n
            while len(out) < k:
                while True:
                    try:
                        z = pop()
                    except IndexError:
                        z = self._mix()
                    if z < limit:
                        break
                j = z % n
                if j not in picked:
                    picked.add(j)
                    out.append(population[j])
            return out
        pool = list(population)
