    """Level order of [isLeaf, val] pairs; every node has four child slots."""
    def node(i):
        v = vals[i]
        if v is None:
            return None
        if not isinstance(v, list) or len(v) != 2:
            raise InputError("node %d must be [isLeaf, val], got %r" % (i, v))
        return QuadNode(bool(v[1]), bool(v[0]))

    if not vals or vals[0] is None:
        return None
    root = node(0)
    queue, head, i = [root], 0, 1
    while i < len(vals):
        if head == len(queue):
            raise InputError("more children than nodes in the level order")
        n = queue[head]
        head += 1
        kids = [node(j) if j < len(vals) else None for j in range(i, i + 4)]
        n.topLeft, n.topRight, n.bottomLeft, n.bottomRight = kids
        queue.extend(k for k in kids if k is not None)
        i += 4
    return root


